211	/// Split a config key on its last `.` into `(section, leaf)`.
212	///
213	/// A path with no `.` (none exist in the current schema) falls
214	/// back to an empty section so the key still renders under a
215	/// blank `[]` header rather than panicking.
216	pub fn section_and_leaf(path: &str) -> (&str, &str) {
217	    match path.rfind('.') {
218	        Some(idx) => (&path[..idx], &path[idx + 1..]),
219	        None => ("", path),
220	    }
221	}
