223	/// Format a raw value string per `kind`, the way a default or an
224	/// example is rendered on the assignment line: `Usize` bare,
225	/// `Str`/`ItemList` quoted.
226	fn format_value(kind: ValueKind, raw: &str) -> String {
227	    match kind {
228	        ValueKind::Usize => raw.to_string(),
229	        ValueKind::Str | ValueKind::ItemList => format!("{raw:?}"),
230	    }
231	}
