233	/// Render a key's value cell: the quoted/bare default, or an
234	/// angle-bracket placeholder by kind when there is no default,
235	/// except a required key with no default, which renders
236	/// `<required>` so it stands out.
237	pub fn render_value(key: &ConfigKey) -> String {
238	    match key.default {
239	        Some(d) => format_value(key.kind, d),
240	        None => {
241	            if key.required {
242	                "<required>".to_string()
243	            } else {
244	                match key.kind {
245	                    ValueKind::Str => "<str>".to_string(),
246	                    ValueKind::Usize => "<usize>".to_string(),
247	                    ValueKind::ItemList => "<items>".to_string(),
248	                }
249	            }
250	        }
251	    }
252	}
