        };
        out.push_str(&format!(
            "    ConfigKey {{\n\
             \x20       path: {path:?},\n\
             \x20       homes: &[{homes}],\n\
             \x20       kind: {kind},\n\
             \x20       default: {default},\n\
             \x20       required: {required},\n\
             \x20       dynamic: {dynamic},\n\
             \x20       doc: {doc:?},\n\
             \x20       used_by: {used_by:?},\n\
