1	//! The settable-config-key registry, generated from the
2	//! `vc-config.toml` prototype at the repo root: build.rs parses
3	//! the prototype and renders the `SCHEMA_GEN` table plus the
4	//! `<PATH>_DEFAULT` constants included below, so the registry,
5	//! the behavioral defaults, and the prototype cannot disagree.
6	//!
7	//! - `crate::config_cmd` prints this registry as an annotated
8	//!   schema, and (with `--validate`) checks a config file's keys
9	//!   against it (dynamic-segment aware).
10	//! - `crate::init` derives init's commented defaults from
11	//!   `schema()`, so these surfaces cannot drift from this list.
12	//! - Behavioral defaults (e.g. `bot-session --col-width`) consume
13	//!   the generated constants rather than hand-kept copies.
14	
15	/// Which config home a key belongs to.
16	/// - `User`: `~/.config/vc-x1/config.toml`
17	/// - `WorkspaceCode` / `WorkspaceBot`: `<root>/.vc-config.toml`
18	///   in the work repo vs the `.claude` bot repo
19	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
20	pub enum Home {
21	    User,
22	    WorkspaceCode,
23	    WorkspaceBot,
24	}
25	
26	/// The value shape a key expects (for rendering / future typed
27	/// use).
28	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
29	pub enum ValueKind {
30	    Str,
31	    Usize,
32	    ItemList,
33	}
34	
35	/// One settable configuration key.
36	pub struct ConfigKey {
37	    /// The config key (TOML table and key joined by `.`), e.g.
38	    /// `"bot-session.col-width"`.
39	    pub path: &'static str,
40	    /// Which home(s) accept this key.
41	    pub homes: &'static [Home],
42	    /// The value shape this key expects.
43	    pub kind: ValueKind,
44	    /// Rendered default, `None` if there is no default.
45	    pub default: Option<&'static str>,
46	    /// Active (not commented) in init; the value is role-specific.
47	    pub required: bool,
48	    /// The path has a `<placeholder>` segment matching a family
49	    /// of keys (e.g. `repo.category.<cat>`).
50	    pub dynamic: bool,
51	    /// One-line description.
52	    pub doc: &'static str,
53	    /// The command/flag or structural context this key is
54	    /// associated with (e.g. `"bot-session --col-width"`).
55	    pub used_by: &'static str,
56	    /// A representative example value for keys with no default;
57	    /// rendered on the assignment line, marked `# example`,
58	    /// instead of a bare placeholder. `None` when the key has a
59	    /// real default (the default serves as the example).
60	    pub example: Option<&'static str>,
61	    /// Docs url for the key, rendered as a `reference:` line so a
62	    /// reader can click through from a generated config.
63	    pub reference: &'static str,
64	}
65	
66	include!(concat!(env!("OUT_DIR"), "/config_schema_gen.rs"));
67	
68	/// Returns the complete registry of settable config keys.
69	pub fn schema() -> &'static [ConfigKey] {
70	    SCHEMA_GEN
71	}
72	
73	/// Split a config key on its last `.` into `(section, leaf)`.
74	///
75	/// A path with no `.` (none exist in the current schema) falls
76	/// back to an empty section so the key still renders under a
77	/// blank `[]` header rather than panicking.
78	pub fn section_and_leaf(path: &str) -> (&str, &str) {
79	    match path.rfind('.') {
80	        Some(idx) => (&path[..idx], &path[idx + 1..]),
81	        None => ("", path),
82	    }
83	}
84	
85	/// Format a raw value string per `kind`, the way a default or an
86	/// example is rendered on the assignment line: `Usize` bare,
87	/// `Str`/`ItemList` quoted.
88	fn format_value(kind: ValueKind, raw: &str) -> String {
89	    match kind {
90	        ValueKind::Usize => raw.to_string(),
91	        ValueKind::Str | ValueKind::ItemList => format!("{raw:?}"),
92	    }
93	}
94	
95	/// Render a key's value cell: the quoted/bare default, or an
96	/// angle-bracket placeholder by kind when there is no default,
97	/// except a required key with no default, which renders
98	/// `<required>` so it stands out.
99	pub fn render_value(key: &ConfigKey) -> String {
100	    match key.default {
101	        Some(d) => format_value(key.kind, d),
102	        None => {
103	            if key.required {
104	                "<required>".to_string()
105	            } else {
106	                match key.kind {
107	                    ValueKind::Str => "<str>".to_string(),
108	                    ValueKind::Usize => "<usize>".to_string(),
109	                    ValueKind::ItemList => "<items>".to_string(),
110	                }
111	            }
112	        }
113	    }
114	}
115	
116	/// Render a key's `default:` note: the quoted/bare default, or a
117	/// parenthetical explaining the absence: `(required; ...)` for a
118	/// required key with no default (role-specific, filled by init),
119	/// `(none)` otherwise.
120	fn render_default_note(key: &ConfigKey) -> String {
121	    match key.default {
122	        Some(d) => format_value(key.kind, d),
123	        None => {
124	            if key.required {
125	                "(required; role-specific, see init)".to_string()
126	            } else {
127	                "(none)".to_string()
128	            }
129	        }
130	    }
131	}
132	
133	/// Word-wrap `text` into `#`-prefixed lines, `first_prefix` on the
134	/// first line and `cont_prefix` on continuations, each kept to
135	/// `width` columns where possible (a single word longer than
136	/// `width` still gets its own line, unsplit).
137	fn wrap_hash_comment(text: &str, first_prefix: &str, cont_prefix: &str, width: usize) -> String {
138	    let mut lines: Vec<String> = Vec::new();
139	    let mut current = String::new();
140	    for word in text.split_whitespace() {
141	        let prefix_len = if lines.is_empty() {
142	            first_prefix.len()
143	        } else {
144	            cont_prefix.len()
145	        };
146	        let sep = usize::from(!current.is_empty());
147	        let tentative_len = prefix_len + current.len() + sep + word.len();
148	        if !current.is_empty() && tentative_len > width {
149	            lines.push(std::mem::take(&mut current));
150	        }
151	        if !current.is_empty() {
152	            current.push(' ');
153	        }
154	        current.push_str(word);
155	    }
156	    if !current.is_empty() {
157	        lines.push(current);
158	    }
159	    let mut out = String::new();
160	    for (i, l) in lines.iter().enumerate() {
161	        let prefix = if i == 0 { first_prefix } else { cont_prefix };
162	        out.push_str(prefix);
163	        out.push_str(l);
164	        out.push('\n');
165	    }
166	    out
167	}
